CREATE SCHEMA IF NOT EXISTS private;
ALTER FUNCTION public.claim_life_ai_request() SET SCHEMA private;
CREATE FUNCTION public.claim_life_ai_request() RETURNS integer LANGUAGE sql SECURITY INVOKER SET search_path = '' AS $$ SELECT private.claim_life_ai_request(); $$;
GRANT USAGE ON SCHEMA private TO authenticated;
GRANT EXECUTE ON FUNCTION private.claim_life_ai_request() TO authenticated;
REVOKE ALL ON FUNCTION public.claim_life_ai_request() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.claim_life_ai_request() TO authenticated;
ALTER TABLE public.buddy_links ADD COLUMN invite_expires_at timestamptz NOT NULL DEFAULT (now()+interval '7 days');
CREATE TABLE public.buddy_attempts (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, attempts integer NOT NULL DEFAULT 0, window_start timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.buddy_attempts TO service_role;
ALTER TABLE public.buddy_attempts ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION private.accept_buddy_safe(_code text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ DECLARE other uuid; me uuid:=auth.uid(); n integer; BEGIN IF me IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF; PERFORM pg_advisory_xact_lock(41192026); INSERT INTO public.buddy_attempts(user_id) VALUES(me) ON CONFLICT DO NOTHING; UPDATE public.buddy_attempts SET attempts=CASE WHEN window_start < now()-interval '1 hour' THEN 1 ELSE attempts+1 END, window_start=CASE WHEN window_start < now()-interval '1 hour' THEN now() ELSE window_start END WHERE user_id=me RETURNING attempts INTO n; IF n>10 THEN RETURN false; END IF; IF EXISTS(SELECT 1 FROM public.buddy_links WHERE user_id=me AND partner_id IS NOT NULL) THEN RETURN false; END IF; SELECT user_id INTO other FROM public.buddy_links WHERE invite_code=upper(btrim(_code)) AND partner_id IS NULL AND invite_expires_at>now() FOR UPDATE; IF other IS NULL OR other=me THEN RETURN false; END IF; UPDATE public.buddy_links SET partner_id=me WHERE user_id=other; INSERT INTO public.buddy_links(user_id,invite_code,partner_id) VALUES(me,replace(gen_random_uuid()::text,'-',''),other) ON CONFLICT(user_id) DO UPDATE SET partner_id=other; RETURN true; END; $$;
REVOKE ALL ON FUNCTION private.accept_buddy_safe(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION private.accept_buddy_safe(text) TO authenticated;
CREATE OR REPLACE FUNCTION public.accept_buddy(_code text) RETURNS boolean LANGUAGE sql SECURITY INVOKER SET search_path = '' AS $$ SELECT private.accept_buddy_safe(_code); $$;
CREATE FUNCTION private.disconnect_buddy_safe() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ DECLARE me uuid:=auth.uid(); BEGIN IF me IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF; PERFORM pg_advisory_xact_lock(41192026); UPDATE public.buddy_links SET partner_id=NULL WHERE partner_id=me; DELETE FROM public.buddy_links WHERE user_id=me; END; $$;
REVOKE ALL ON FUNCTION private.disconnect_buddy_safe() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION private.disconnect_buddy_safe() TO authenticated;
CREATE FUNCTION public.disconnect_buddy() RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path = '' AS $$ SELECT private.disconnect_buddy_safe(); $$;
REVOKE ALL ON FUNCTION public.disconnect_buddy() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.disconnect_buddy() TO authenticated;
CREATE FUNCTION private.limit_community_messages() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ BEGIN PERFORM pg_advisory_xact_lock(hashtext(NEW.user_id::text)); IF (SELECT count(*) FROM public.community_messages WHERE user_id=NEW.user_id AND created_at>now()-interval '1 minute')>=5 THEN RAISE EXCEPTION 'Bir daqiqada ko‘pi bilan 5 xabar'; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION private.limit_community_messages() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER community_message_rate BEFORE INSERT ON public.community_messages FOR EACH ROW EXECUTE FUNCTION private.limit_community_messages();